insert into public.publishers (exhibitor_no, booth_number, original_booth_number, name, name_en, country_ko, country_en, is_special, categories, introduction, homepage, instagram, sort_order) values
  (220, 'A702', null, '타이피스트', 'Typist Press', null, null, false, array['예술','문학']::text[], '2023년 창업한 타이피스트 출판사는 시인 박은정이 대표로 운영하는 1인 출판사입니다. 시와 에세이를 중심으로 한 다양한 기획을 통해, 동시대 문학이 독자들의 일상 가까이 스며들 수 있도록 꾸준히 고민하고 있습니다. 을 비롯한 출간물들은 문학나눔 선정 및 각종 문학상 수상과 후보작 선정 등을 통해 작품성과 기획력을 인정받아 왔으며, 특히 젊은 독자층의 지속적인 관심과 호응 속에서 독자 기반을 넓혀가고 있습니다. 타이피스트는 작가의 고유한 목소리와 언어를 존중하는 편집을 바탕으로, 오래 곁에 남는 책을 만들고자 합니다.', null, 'https://www.instagram.com/typistpress/', 220),
  (221, 'A703', null, '사단법인 한국대학출판협회', 'THE ASSOCIATION OF KOREAN UNIVERSITY PRESSES', null, null, false, array['총류','사회과학','언어']::text[], '사단법인 한국대학출판협회는 국내 대학출판부 간의 상호 협력과 학술출판 발전을 위해 설립된 단체입니다. 전국 대학출판부를 회원으로 하여 학술서적의 질적 향상과 출판 유통 활성화를 도모하고 있습니다. 또한 공동 전시회, 세미나, 정보 교류 사업 등을 통해 출판 역량을 강화하고, 대학의 연구 성과가 사회 전반에 널리 확산될 수 있도록 지원하고 있습니다. 아울러 회원 기관 간 협력 네트워크를 구축하여 학술정보 공유를 촉진하고, 출판 환경 변화에 대응하는 다양한 사업을 추진하고 있습니다. 이를 통해 학술출판의 공공성과 전문성을 제고하고, 건강한 출판 문화 조성에 기여하고 있습니다.', 'http://akup.co.kr', null, 221),
  (222, 'A704', null, '도서출판 북극곰', 'BOOKGOODCOME', null, null, false, array['총류','문학','아동']::text[], '도서출판 북극곰은 2009년에 설립되어 환경, 상생, 치유라는 주제로 어린이도서와 교양도서를 출간합니다. 좋은 책은 우리 영혼의 양식이 된다는 믿음으로 웃기거나 찡하거나 우리 마음에 울림을 주는 책을 만들어 왔습니다. 이루리 볼로냐 그림책 워크샵 등 여러 프로그램을 통해 신인 작가를 발굴하고, 그림책 애호가의 확산에 힘쓰고 있습니다. 또한 그림책의 행복을 널리 알리기 위해 다양한 작가 강연 프로그램도 운용하고 있습니다. 볼로냐, 프랑크푸르트 도서전 등 다양한 해외도서전에 정성껏 만든 책을 선보이고, 세계 각국에 수출합니다. 북극곰의 책은 현재까지 16개 언어로 번역 출간되어 독자들을 만나고 있습니다. 북극곰은 재미있고 아름다운 책을 만들어 독자들이 더욱 행복한 세상을 만드는 데 기여하고자 합니다.', 'http://www.bookgoodcome.com', 'https://instagram.com/bookgoodcome/', 222),
  (223, 'A705', null, '국민서관', 'KOOKMINBOOKS', null, null, false, array['아동']::text[], '국민서관은 한국을 대표하는 어린이 출판사로, 1961년 설립되었습니다. 유아와 아동 도서를 전문으로 출간하고 있으며, 지금까지 약 1,900여 종에 달하는 책을 출간해 왔습니다. 권정생, 홍종의, 박현숙, 윤미경 등 국내 유명 작가와 로렌 차일드, 제인 오코너, 막스 뒤코스, 시드니 스미스 등 해외 유명 작가의 작품들을 국내외의 독자들에게 소개했습니다. 국민서관 도서는 미국, 프랑스, 중국, 일본 등 여러나라에 번역되어 출간되고 있습니다.', null, 'https://www.instagram.com/kookminbooks/', 223),
  (224, 'A706', null, '주식회사 성안당', 'SungAnDang Publishing Inc.', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '1973년 설립된 (주)성안당은 대한민국을 대표하는 과학기술 도서 및 자격증 전문 출판사입니다. 경기도 파주출판단지에 본사를 두고 있으며, 지난 50여 년간 ''기술 강국 대한민국''의 토대를 닦는 데 기여해 왔습니다. 성안당은 특히 IT컴퓨터, 전기전자, 소방안전 등 공학 전 분야의 전문 서적과 국가기술자격 시험 대비 수험서로 높은 명성을 쌓아왔습니다. 또한 시대의 흐름에 맞춰 성안당 e러닝과 같은 온라인 교육 콘텐츠를 제공하고, 성안북스, 황금부엉이 등 계열사를 통해 실용, 경제경영, 아동 도서까지 범위를 넓히며 종합 콘텐츠 그룹으로 성장하고 있습니다. 전문성과 정확성을 최우선으로 하는 성안당은 앞으로도 독자들에게 신뢰받는 지식 정보를 전달하며 미래 인재 양성에 힘쓸 것입니다.', 'https://www.cyber.co.kr/book/', 'https://www.instagram.com/sungandang/', 224),
  (225, 'A707', null, '책읽는고양이', 'Reading Cat', null, null, false, array['문학','역사','기타(인문)']::text[], '책읽는고양이는 동물병원 안에 있는 작은 출판사입니다. 동물병원과 출판사를 오가는 고양이들은 종종 책 위에서 휴식을 청합니다. 무심한 듯 우아하게 나 자신을 찾아 떠나는 여행 같은 책을 펴냅니다.', 'http://risu.co.kr', null, 225),
  (226, 'A708', null, '소미미디어', 'SOMYMEDIA Inc.', null, null, false, array['문학','전자출판','기타(웹툰','만화)']::text[], '소미미디어는 ‘소미북스’ ‘소미웹툰’ ‘S노벨’ ‘S코믹’ 등의 다양한 출판콘텐츠 브랜드를 보유하고 있습니다. 소미미디어는 한국의 문화 콘텐츠 업계를 선도하며 종합출판사를 지향하는 콘텐츠 전문 기업입니다. 특히 책을 좋아하는 다양한 독자에게 알찬 내용과 감동, 재미를 맛볼 수 있는 양질의 콘텐츠를 선보이고자 끊임없는 연구개발에 매진하고 있습니다. 소미미디어는 앞으로도 재미있는 콘텐츠, 양질의 콘텐츠를 개발하기 위한 기획과 연구를 통해 남녀노소 모두에게 사랑받는 종합출판콘텐츠 기업으로 성장하겠습니다.', 'https://blog.naver.com/somybooks', null, 226),
  (227, 'A709', null, '고래인', 'goraein', null, null, false, array['총류','문학','아동']::text[], '고래인(古來人)은 옛날부터 현재까지 살아온 사람이라는 뜻으로 우리의 마음 안에 하나씩 새겨져 전해 오는 문화 유전자를 의미합니다. 그 속에 담긴 이야기를 다양한 문화 콘텐츠로 생산합니다. 고래뱃속은 고래인의 어린이 책 브랜드로서 그림책, 아동문학, 논픽션 분야의 책을 출판합니다. 시간도 중력도 느껴지지 않는 곳, 두둥실 몸이 떠오를 것 같은 곳, 고래뱃속은 이야기가 끝없이 펼쳐지는 상상 놀이터입니다.', 'http://www.goraein.com', 'https://www.instagram.com/goraebaetsok/', 227),
  (228, 'A709', null, '키큰도토리', 'Kikeundotori Publishing Co.', null, null, false, array['아동']::text[], '어린이의 마음을 크게 하는 책.어린이의 마음을 건강하게 하는 책. 키큰도토리는 어린이의 마음을 더 크고, 건강하게 하는 책을 만듭니다. 그림책, 어린이창작동화, 판타지동화, 어린이교양도서를 출간하고 있습니다.', 'http://kkdotori.com/', 'https://www.instagram.com/kkdotori/', 228),
  (229, 'A801', null, '부산출판문화산업협회', 'Busan Publishing and Culture Industry Association', null, null, false, array['사회과학','예술','문학']::text[], '부산을 기반으로 책을 출간하는 출판사들이 연대하여 만들어진 조직입니다. 쉽지 않은 지역출판의 현실 속에서 연대의 필요성을 느끼고 다양한 분야의 책을 출간하는 30여 개 출판사들이 뜻을 모았습니다. 부산만의 감수성은 지역출판이 더 잘 담아낼 수 있다는 마음으로 더 많은 독자들에게 로컬 콘텐츠의 매력을 전하고자 합니다.', null, 'https://www.instagram.com/busanpcia/', 229),
  (230, 'A801', null, '고양이함수', 'Cat Function', null, null, false, array['예술','문학','아동']::text[], '고양이함수는 이미지와 텍스트를 결합하여 시각 서사를 확장하는 작가들의 책을 만듭니다. 우리는 창작의 과정이 지닌 다양한 기능 중 ‘즐거움’과 ‘회복’을 중심에 두고, 인간과 동물, 예술과 삶에 대한 서사를 그림과 글이 함께 있는 책으로 엮어냅니다. 더불어 창작의 경험이 특별한 소수의 영역을 넘어 모두의 보편적 즐거움으로 확장될 수 있도록 창작 워크북을 연구하고 개발합니다. 우리는 창작을 통해 개인의 고유한 서사를 발굴하고, 일상이 예술로 전환되는 기록의 힘을 믿습니다.', null, 'https://www.instagram.com/catfunction_/', 230),
  (231, 'A801', null, '공공북스', 'Gonggong books', null, null, false, array['문학','기타(아티스트북)']::text[], '공공북스는 부산을 기반으로 활동하는 출판사로, 아티스트와의 협업을 통해 책을 기획·편집·디자인·제작까지 통합적으로 수행합니다. 작가의 작업과 세계관이 책이라는 매체 안에서 하나의 구조와 경험으로 구현되도록 돕고, 독립출판과 아티스트북을 중심으로 다양한 형식의 출판을 시도합니다. 부산이라는 로컬에서 출발해, 책을 매개로 예술과 지역, 사람을 연결하는 출판을 만들어가고 있습니다.', null, 'https://www.instagram.com/gonggong_books/', 231),
  (232, 'A801', null, '냥이의야옹', 'NYAONGBOOKS', null, null, false, array['문학','아동']::text[], '냥이의야옹’은 부산에서 시작된 독립출판사입니다. 우리는 모든 존재가 각자의 목소리로 세상에 말을 걸 수 있다고 믿습니다. 작고 느린 이야기, 지역의 삶과 감각, 사라져가는 공간과 기억을 기록하며 ‘나의 언어로 말하는 책’을 만듭니다. 기획 시리즈 『부산,머물다』와 지역문화 매거진 『B.B.A.L.』 그리고 부산의 장소성과 삶을 담은 도서들은 지역에서 출발하지만 지역에 머물지 않는 확장된 감각을 지향합니다.', null, 'https://www.instagram.com/nyaongbooks/', 232),
  (233, 'A801', null, '뮤트스튜디오', 'Muut Studio', null, null, false, array['예술']::text[], '부산출판협회 부스로 참가하는 뮤트스튜디오는 부산을 기반으로 활동하는 시각예술 전문 출판사다. 동시대 미술 비평서를 중심으로 부산기반 시각예술가의 아티스트북과 부산 미술사를 다루는 출판물을 꾸준히 발간하며 지역 예술 담론을 축적해왔다. 이번 도서전에서는 주요 비평서와 아티스트북을 소개할 예정이다.', 'http://muutstudio.com', null, 233),
  (234, 'A801', null, '씨엘미디어', 'CLmedia', null, null, false, array['사회과학','문학','아동']::text[], '씨엘미디어는 캐릭터 ''와이키키남매''와 함께 창의적인 생각이 담긴 책과 영상, 음악 등으로 따뜻한 이야기를 전합니다.', 'http://blog.naver.com/kogeang', null, 234),
  (235, 'A801', null, '해피북미디어', 'happybook media', null, null, false, array['총류','예술','문학']::text[], '해피북미디어는 2009년 부산에서 시작한 출판사로 부산의 예술문화와 예술인을 소개하는 ‘예술문화 총서’ 시리즈를 주축으로 하여 반짝이는 로컬의 문화를 알리고자 합니다. 예술문화총서 시리즈 첫 번째 책으로 『청중의 발견』(2011)를, 2023년에는 열한 번째 시리즈인 『부산에서 찾아보는 이중섭 흔적』을 출간하였습니다. 환경, 여성, 소수자 등의 문제에 관심을 갖고 책을 매개로 하여 그 목소리를 전달하고자 합니다. 2025년에는 이 세종도서 학술부문에 가 대한민국학술원 우수학술도서에 선정되었습니다. , , 를 출간하며 부모와 아이 모두 행복한 교육 방식을 제시하고자 합니다.', null, 'https://www.instagram.com/happybook_media/', 235),
  (236, 'A802', null, '주식회사 소원나무', 'SOWONNAMU PUBLISHING CO,. LTD.', null, null, false, array['예술','문학','아동']::text[], '소원나무는 한 권의 책 속에 우리의 꿈과 희망을 소중하게, 정성스럽게, 웅숭깊게 담아내는 출판사입니다. 2013년부터 지금까지 그림책, 동화, 청소년 소설, 성인 에세이 등을 두루 출간해 오고 있습니다. 대표작으로는 그림책 와 , 어린이책 와 , 청소년 소설이자 제1회 소원문학상 수상작인 등이 있습니다. 소원나무 책에는 우리 삶에 필요한 기쁨, 슬픔, 위로, 응원, 용기, 희망이 가득 담겨 있고 사람을 향한 따스한 시선이 고스란히 녹아 있습니다. 소원나무는 늘 그 자리에 있어 주는 나무처럼, 마음속 소원을 응원해 주는 친구처럼 독자 여러분 곁에 있겠습니다. 오늘도 소원나무 책과 함께 행복하시기를 바랍니다.', 'https://www.sowonnamu.co.kr', 'https://www.instagram.com/sowonnamu/', 236),
  (237, 'A803', null, '뜨인돌출판', 'Danielstone Publishing', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '"분명한 뜻이 담긴 책"을 출간하겠다는 목표 아래 ''독자들이 시대를 읽고 사유하며 행동하는'' 인문 서적, ''삶에 위로와 힘을 주는'' 비소설 서적, ''주체적으로 사고하고 창의적으로 문제를 해결할 수 있는 능력을 키워주는'' 청소년 서적, 그리고 ''꿈, 도전정신, 지혜를 키워주는'' 어린이 서적을 출간하고 있습니다. 시리즈와 를 통해 독자들에게 많이 알려졌습니다. 새롭고 참신한 기획, 사회의 구석구석까지 바라보는 예리한 시선, 나누고 배려하는 따뜻한 마음, 그리고 책에 대한 애정을 갖고 더 나은 세상을 만들기 위해 노력하는 출판사가 되겠습니다.', 'http://www.ddstone.com', null, 237),
  (238, 'A804', null, '밝은미래', 'Balgeunmirae Publishing Co', null, null, false, array['아동']::text[], '2005년 어린이 책 출판사로 시작했습니다. 국내외 창작 동화를 비롯하여 그림책, 주니어 소설, 그래픽노블, 지식 정보책, 학습 만화 등을 출판하고 있습니다. 2006년에는 KBS TV ''위기탈출 넘버원''을 어린이 학습 만화로 만들어, 어린이 안전 교육에 커다란 전기를 만들었습니다. 20년간 어린이의 밝은 미래를 키울 수 있는 좋은 책을 전하고자 노력해 왔으며, 책이 줄 수 있는 즐거움을 어린이들이 누릴 수 있도록 하였습니다. 책이 줄 수 있는 즐거움은 단지 웃음이 아닙니다. 희로애락이 살아 숨쉬고 감동을 전하는 스토리가 책이 줄 수 있는 즐거움이고, 알고 싶은 호기심을 자극하고 하나씩 지식을 알고 탐험하는 것 또한 책이 줄 수 있는 즐거움입니다. ''책이 가진 최고의 즐거움''을 선사하는 밝은미래가 되겠습니다', 'http://www.bmirae.com', 'https://www.instagram.com/balgeunmirae1/', 238),
  (239, 'A805', null, '도서출판 동녘', 'Dongnyok publishers', null, null, false, array['철학','사회과학','아동']::text[], '생각의 자유조차 허용되지 않던 1980년 봄, 시대의 어둠을 밝히는 촛불이 될 것을 자임하며 도서출판 동녘이 탄생했습니다. 1980년대에 펴낸 , , 등이 독자들의 폭발적인 호응과 공감을 얻어 동녘을 손꼽히는 진보 출판사로 키워 주었습니다. 1990년대에는 인문교양서, 여성학 도서, 재미있고 유익한 청소년 책을 내는 데 힘쓰는 한편, 나의 라임오렌지나무 시리즈를 새롭게 펴냈습니다. 동녘은 독자와 시대의 요구에 귀 기울이며, 다양한 분야에서 좋은 책을 만들고자 노력하고 있습니다. 앞으로도 나날이 깊이를 더하고 지평을 넓혀, 풍요롭고 건강한 문화 지형도를 그릴 수 있는 책을 만들겠습니다.', 'https://www.dongnyok.com/', 'https://www.instagram.com/dongnyokpub/', 239),
  (240, 'A806', null, '클레이하우스 주식회사', 'CLAYHOUSE', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '2021년 2월 출범한 클레이하우스는 실용적 따뜻함을 출판 철학으로 삼는 브랜드입니다. 예술적 실험보다 독자의 일상에 유효한 아름다움을 고민하며, 끝까지 읽히는 책을 만듭니다. 위로와 실용이 공존하는 세계, Into the Feel-Good Universe를 지향하며 삶에 직접 닿는 이야기로 조용한 변화를 제안합니다. 도덕적 마케팅과 인간 중심 협업을 바탕으로, 국내를 넘어 글로벌 감각의 콘텐츠를 기획수출하는 단단한 K-출판사입니다.', 'https://clayhouse.kr', null, 240),
  (241, 'A807', null, '보스토크 프레스', 'VOSTOK PRESS', null, null, false, array['예술','문학']::text[], '보스토크 프레스는 사진을 중심으로 디자인과 현대미술, 문학 등을 다루는 출판사입니다. 사진잡지 보스토크 매거진과 다양한 예술 관련 단행본을 발간하며, ‘보스토크 메리고라운드’를 비롯한 작가 행사와 세미나, 강의와 워크샵 등도 기획합니다. 또한 기관과 회사를 위한 다양한 출판 프로젝트를 병행하고 있습니다.', 'http://vostokpress.net/', 'https://www.instagram.com/vostok_mag/', 241),
  (242, 'A807', null, '프리즘오브', 'PRISM OF', null, null, false, array['사회과학','예술']::text[], '프리즘오브 프레스에서 발간되는 프리즘오브(PRISM OF)는 매 호 한 영화에 대한 다양한 시선을 담는 계간 영화잡지입니다. Prism과 Of의 합성어로 영화에 대한 프리즘, 영화를 바라보는 사람들의 프리즘을 담는다는 의미를 지니고 있습니다. 작품을 여러 각도에서 재조명하여 관객의 영화적 경험을 확장시키며 소장가치 있는 매거진을 지향합니다.', null, 'https://www.instagram.com/prismof_magazine/', 242),
  (243, 'A808', null, '진선출판사', 'Jinsun Publishing', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '진선출판사(주)는 소중한 가치를 담은 어린이, 자연, 예술 책을 펴내는 곳으로 어린이의 마음과 생각을 키워 주는 어린이 도서 브랜드 진선아이, 자연의 향기와 창작의 기쁨이 가득한 성인 도서 브랜드 진선북스의 출판 브랜드가 있습니다. 1988년을 시작으로 해서 그동안 다양한 자연 생태 일기 시리즈, 자연 과학 도서, 미술 취미 단행본, 각종 도감 등을 출간해 왔습니다. 지금까지 800여종의 책을 펴냈으며, 많은 책이 문화체육관광부를 비롯한 여러 기관과 단체의 우수 도서로 선정되었습니다.', 'http://www.jinsun.co.kr', 'https://www.instagram.com/jinsunbook/', 243),
  (244, 'A901', null, '윌북', 'Willbooks Publishing Co.', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '윌북은 2004년에 설립된 단행본 출판사입니다. 예술, 대중문화, 에세이, 인문 교양 등의 책을 출간하고 있습니다. 우리가 독서를 통해 저자의 어깨 위에 올라 더 먼 곳을 볼 수 있도록 윌북은 오늘도 거인의 어깨가 되어줄 한 권의 책을 만들고 있습니다.', 'http://willbookspub.com', 'https://www.instagram.com/willbooks_pub/', 244),
  (245, 'A902', null, '더중앙플러스', 'The JoongAng Plus', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '중앙일보는 ''중앙에 두다''를 슬로건으로 현장의 진실, 통합의 가치, 내일의 성장을 중앙에 두겠다는 의지를 담은 국내 대표 종합일간지입니다. 2022년 10월 국내 종합일간지 최초로 유료 구독 서비스 ''더중앙플러스(The JoongAng Plus)''를 시작했으며, 커리어 전문 콘텐트 서비스 ''폴인(fol:in)'', 블룸버그와 함께하는 미국 주식 투자자 대상 프리미엄 금융 정보 플랫폼 ''Global Money Club'' 등 혁신적인 디지털 서비스를 운영하고 있습니다. 취재, 분석, 데이터 기반 콘텐트를 강화해 독자에게 더 깊은 인사이트를 제공하고, 저널리즘의 깊이와 독자 경험을 함께 높이는 디지털 전환을 지속합니다. 또한 뉴욕타임스, 블룸버그, CNN 등과의 제휴를 바탕으로 글로벌 네트워크를 구축하고 있습니다.', 'https://www.joongang.co.kr/', 'https://www.instagram.com/joongangilbo/', 245),
  (246, 'A903', null, '동아시아·허블', 'EAST-ASIA·Hubble', null, null, false, array['사회과학','순수과학','문학']::text[], '동아시아 출판사는 과학과 인문학 분야를 축으로 탄탄한 기획력을 선보여온 출판사로, 과학 기술의 변화와 사회적 이슈를 긴밀하게 연결하며, 동시대 독자에게 필요한 지식과 질문을 제시합니다. SF 문학 브랜드 ''허블''을 비롯해, 과학 잡지 분야의 ''메이커스'', 문학예술을 아우르는 ''물결점'', 의학생명과학 분야를 다루는 ''히포크라테스''의 다양한 브랜드를 운영하며 폭넓은 출판 스펙트럼을 구축하고 있습니다. 최근 장강명 작가의 , 천선란 작가의 를 출간하며 사회적 현실과 문학적 상상력을 아우르는 작품들을 선보였습니다. 동시대의 구조적 변화와 인간의 삶을 밀도 있게 포착하는 작업을 통해, 논픽션과 문학의 경계를 넘나들며 사회를 사유하는 힘을 지속적으로 이어가겠습니다.', null, 'https://www.instagram.com/dongasiabook/', 246),
  (247, 'B101', null, '어크로스', 'Across Publishing Group, Inc', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '어크로스출판그룹(주)은 통합적 지식과 사유가 담긴 인문사회과학경제예술 분야의 교양서, 인간과 삶을 성찰하는 에세이, 흥미로운 이야기와 지식이 생활의 지혜로 거듭나는 어린이책 등을 출간하는 단행본 출판사입니다. 어크로스는 지식이 지혜가 되는 순간을 꿈꿉니다. 인류가 연구하고 공부해 알아낸 지식이 책에 담겨 우리의 삶을 더 풍요롭고 가치 있게 만드는 지혜로 바뀔 수 있도록 하는 것이 어크로스의 바람입니다. 미래를 내다보고 오늘을 살아갈 힘이 되는 지식과 교양을 발견하는 일, 이를 찾아 독자에게 다가가는 일, 독자들이 더 깊이 사유하고 상상력을 확장할 수 있게 돕는 일은 어크로스의 영원한 화두입니다.', 'http://acrossbook.com', 'https://www.instagram.com/across_book/', 247),
  (248, 'B102', null, '움직씨 출판사', 'Oomzicc Publisher', null, null, false, array['사회과학','문학','아동']::text[], '움직씨 출판사는 퀴어 페미니즘 출판사로 감각과 혁명을 중시하는 편집인과 작가가 만든 다양성 출판사입니다. LGBTQ+ 인권과 젠더, 계급에 관한 문학, 그래픽 노블, 사회과학, 인문, 교양 책을 다룹니다. 여성과 퀴어 소수자의 목소리를 드높이는 책을 펴냅니다. 전미도서상 수상 작가 가브리엘라 카베손 카마라의 치나 아이언의 모험과 타이완 에세이 나의 부치 엄마를 신간으로 선보입니다. 펴낸 책으로 그래픽 노블 작가 앨리슨 벡델의 초인적 힘의 비밀, 펀 홈, 당신 엄마 맞아?, 타이완 퀴어 문학의 최고작인 구묘진의 소설 악어 노트, 몽마르트르 유서, 흑인 페미니스트 오드리 로드의 시집 블랙 유니콘, 슬로베니아 시인 브라네 모제티치의 시시한 말, 첫사랑, 공동 대표이자 작가 노유다의 코끼리 가면 등이 있습니다.', 'http://oomzicc.com', null, 248),
  (249, 'B102', null, '오리집', 'ORIZIP', null, null, false, array['예술','문학']::text[], '오리집은 밝고 명랑한 레즈비언 문화를 선도하는 출판사로 2022년부터 독립 문예지 를 발간하고 있습니다. 소수자가 스스로 발언하고자 하는 갈증을 포착하며, 주변화되기 쉬운 퀴어의 창작에 집중합니다. 오리집은 ‘철새 같은 사람들이 쉬어갈 곳’이라는 뜻으로, 오리집이 위치한 지역사회와 함께 호흡하며 정체성을 탐구하는 레즈비언들의 목소리를 놀이와 예술의 방식으로 세상에 기입하고 있습니다. 레즈비언 행진 ‘다이크 마치 코리아’, 레즈비언 예술가 자생 프로젝트 ‘덕셸터’ 등을 진행하며 정체성을 탐구하는 소수자를 환대하고 기입하며 가시화하는 창작 문화를 만듭니다. 이를 통해 레즈비언, 페미니스트, 여성 예술가 들이 교류할 수 있는 공간 기반으로 성장하고 있습니다.', null, 'https://www.instagram.com/orizip/', 249),
  (250, 'B103', null, '(주)책읽는곰', 'Bear Books Inc.', null, null, false, array['아동']::text[], '"책읽는곰은 무엇이든 될 수 있는 아이에게 무엇이든 주고 싶은 부모의 마음으로 어린이책을 만듭니다." 2006년 어린이책 전문 출판사로 시작한 책읽는곰은 우리 작가가 쓰고 그린 창작 그림책 ''그림책이 참 좋아'' 시리즈로 어린이들의 큰 사랑을 받아왔습니다. 최숙희, 윤정주, 김영진, 유설화 작가를 비롯한 한국의 대표적인 그림책 작가들과 함께 협업하고 신인 작가를 꾸준히 발굴하고 있습니다. 그밖에도 어린이의 문해력 향상과 읽기 독립을 위한 ''678 읽기독립'' 시리즈, 한국 문화를 흥미진진한 이야기에 담은 ''온고지신'' 시리즈, 다양한 분야의 지식 정보를 그림책 형태로 만든 ''지식곰곰'', ''생각곰곰'' 시리즈와 어린이를 위한 문학 ''큰곰자리'' 시리즈 등 다양하고 참신한 도서를 펴내고 있습니다.', 'http://bearbooks.co.kr', null, 250),
  (251, 'B104', null, '페이퍼독', 'PAPERDOG', null, null, false, array['아동']::text[], '페이퍼독 출판사는 "철학이 있고 재미있는 국내 창작 그림책을 만든다"라는 모토로 현재 까지 10권의 책이 출간되었습니다. 이 중 개꿈, 불량감자는 2023, 2025년도 볼로냐도서전 올해의 일러스트레이터를 수상하였고, 어떻게 추는 거야?는 2025 북스타트에 선정되었습니다. 지옥고양이는 2024문화체육관광부 지원 사업에, 넌, 없어!는 2023한국출판문화산업진흥원 창작 지원 사업에 선정 되었습니다. 작지만 색깔있는 페이퍼독 출판사는 26년도는 국내는 물론 해외 진출을 위해 ,한 권 한 권 최선을 다해 색깔 있는 우리 창작 그림책을 만들어 가겠습니다.', null, 'https://www.instagram.com/paperdog_books/', 251),
  (252, 'B104', null, '토끼섬', 'Tokkiseom', null, null, false, array['문학','아동']::text[], '토끼섬은 아이들의 마음을 닮은 그림책을 만드는 출판사입니다. 빠르게 소비되는 이야기가 아니라 오래 곁에 머물며 아이들의 마음을 다독이고, 스스로를 이해하도록 돕는 책을 만듭니다. 일상의 작은 감정과 성장의 순간을 섬세하게 담아내며, 아이와 어른이 함께 읽고 공감할 수 있는 이야기를 지향합니다. 그림과 글, 디자인이 조화롭게 어우러진 책을 통해 독자에게 따뜻한 위로와 깊은 여운을 전하고자 합니다. 토끼섬은 한 권 한 권에 진심을 담아 아이들의 시간 속에 오래 남는 책을 만들어갑니다.', null, 'https://www.instagram.com/tokkiseom_book/', 252),
  (253, 'B105', null, '송송책방', 'SONGSONG BOOKS', null, null, false, array['예술','문학','아동']::text[], '송송책방은 만화와 그래픽노블, 에세이를 중심으로 국내외 작가의 작품을 한국 독자에게 소개하는 출판사이자 책방입니다. 2017년 설립 이후 음식, 일상, 취향을 주제로 한 만화와 에세이를 기획, 출간해왔습니다. 대표 도서로는 잼잼 시리즈가 있으며, 번역서와 국내 창작 만화를 함께 다룹니다. 책방에서는 그래픽노블과 음식생활 에세이를 중심으로 큐레이션하여 독자와 만나고 있습니다.', 'http://www.songsongbooks.com', null, 253),
  (254, 'B106', null, '꿈공장플러스', 'DREAMBOOKS', null, null, false, array['문학']::text[], '꿈공장플러스는 보통 사람의 이야기에 귀를 기울입니다. 지난 10년간 저희는 시, 에세이, 그리고 소설을 통해 많은 이들의 이야기를 세상에 내놓았습니다. 독자와 함께 성장하는 작가들의 모습은 꿈공장플러스의 존재 이유가 되어주기도 합니다. 갈수록 인간성을 잃어버리는 시대, 문학은 하나의 버팀목이라 굳게 믿습니다. 글로 세상을 밝히는 사람들. 그 곁에 꿈공장플러스는 단단한 디딤돌로 기억되고 싶습니다.', 'http://www.dreambooks.kr', 'https://www.instagram.com/dreambooks.ceo/', 254),
  (255, 'B107', null, '아카넷', 'Acanet', null, null, false, array['총류','철학','역사']::text[], '아카넷은 그동안 우리 학계에서 가장 필요로 하는 학술서적을 발간해 오면서 학술 출판사로서의 탁월한 전문성과 편집 역량을 축적해 왔습니다. 이를 토대로 신규 전문 학술 서적뿐 아니라 학계에 필수적인 고전들을 엄선해 지속적으로 번역출간함으로써 우리 학계의 학문적 발전에 기여할 것입니다. 빛의 속도로 팽창과 성장을 거듭하는 지식산업의 현장에서 아카넷은 전통적인 인쇄출판을 기반으로 새로운 정보통신기술의 발전이 가져올 변화된 출판환경에 적극 대처하려는 의욕과 열정을 추구합니다. Acanet은 학술 분야의 가치 있는 콘텐츠를 도서출판을 통해 우리 사회 전체가 폭넓게 공유하는 데 기여하고자 하며 이를 통해 우리 사회 다양한 분야와 계층의 소통이 이루어지고 건강하게 살아있는 네트워크가 형성되기를 소망합니다.', 'http://www.acanet.co.kr/', null, 255),
  (256, 'B108', null, '디자인이음', 'designEUM', null, null, false, array['예술','문학']::text[], '디자인이음은 삶에 긍정적인 영향을 미치는 다양한 책을 만드는 출판사입니다. 감각적인 디자인의 문고판으로 고전 문학을 새롭게 만나는 ''이음문고'' 시리즈, 독립출판 작가들의 빛나는 작품을 소개하는 ''청춘문고'' 시리즈, 두 명의 시인이 함께 만드는 ''우정시집'' 시리즈를 비롯해 감성적이면서도 깊이 있는 단행본을 출간해오고 있습니다. 더불어 , 한국어판과 같은 라이프스타일 매거진과 여행,예술,요리 분야의 실용서도 꾸준히 소개하고 있습니다. 책을 기반으로 소소한 일상에 새로운 감성과 문화를 공유합니다.', 'https://blog.naver.com/designeum/', null, 256),
  (257, 'B109', null, '컬처룩', 'culturelook', null, null, false, array['사회과학','순수과학','예술']::text[], '컬처룩은 다양한 지식 세계를 넘나들고 아우르는 책을 만들고자 2012년 문을 열었습니다. 인문사회과학, 자연과학, 예술 분야의 책을 펴내고 있습니다. 특히 커뮤니케이션미디어, 문화연구, 영화 분야에 주목해 본질적이고 주요한 주제를 심도 있고 다양한 시각으로 들여다봅니다. 컬처룩이 주목하는 또 다른 축은 과학 분야로, 주제별로 깊이 있는 내용을 흥미롭게 전달하는 책을 펴내고 있습니다. 특히 수학은 다양한 분야와 접목한 책들을 펴내 큰 주목을 받고 있습니다.', 'http://culturelook.net', null, 257),
  (258, 'B109', null, '코쿤북스', 'cocoonbooks', null, null, false, array['사회과학','순수과학','예술']::text[], '“책 속에서 우리는 외롭지 않습니다.” 코쿤북스는 독자에게 변치 않는 안식처이자, 지적·개인적 성장을 위한 따뜻한 ‘고치(cocoon)’가 되는 것을 지향합니다. 우리는 다양한 분야에 존재하는 작지만 깊은 울림을 가진 목소리를 세상에 전하는 확성기가 되고자 합니다. 또한 책을 통해 독자의 삶에 ‘변태(metamorphosis)’와 같은 질적 변화를 이끌어냄으로써, 우리 공동체가 더욱 다채롭고 활기차며 건강한 방향으로 나아가는 데 기여하고 싶습니다. 우리는 과학, 예술, 사회적 담론의 영역에서 우리 시대의 ‘다음(next)’ 공감대를 형성할 새로운 가치를 찾는 데 역량을 집중하고 있습니다.', null, 'https://www.instagram.com/cocoon_books/', 258),
  (259, 'B201', null, '유유출판사', 'UU PRESS', null, null, false, array['총류','사회과학','언어']::text[], '작고 단단하게, 재미있게ㅡ 유유는 독자의 공부를 돕는 책을 만듭니다. 스스로의 내면을 단단하게 만드는 공부가 유유가 지향하는 목표이며, 독자가 이 목표를 스스로 구현할 수 있도록 돕는 책을 펴냅니다. 유유의 책은 환경을 위해 재생지를 사용합니다. 작고 가벼워서 언제 어디서나 편히 들고 다니며 읽을 수 있습니다.', 'http://uupress.co.kr', null, 259),
  (260, 'B202', null, '바람북스', 'BARAMBOOKS', null, null, false, array['예술','문학']::text[], '바람북스는 성인 독자와 함께 읽을 수 있는 책을 만들기 위해 바람의아이들에서 런칭한 브랜드입니다. 첫번째 주제인 여성 서사를 시작으로, 노인, 동물, 자연, 기후 등 기존 제도와 질서로부터 배제된 모든 약자의 이야기에 귀를 기울이는 이야기를 펴내고 있습니다. 보다 넓고 보다 깊은, 휴머니즘 너머의 휴머니즘을 지향하며 그래픽노블을 비롯한 인문예술 분야의 아름다운 책들을 지어나가려 합니다.', 'https://www.barambooks.net/barambooks', 'https://instagram.com/baramkids.kr/', 260),
  (261, 'B203', null, '레모 출판사', 'LES MOTS', null, null, false, array['철학','예술','문학']::text[], '레모출판사는 2017년 좋아하는 책을 정확한 번역으로 한국어 독자에게 소개하겠다는 목표로 설립된 프랑스 문학 전문 출판사입니다. 레모(LE MOTS)는 프랑스어로 단어, 말을 뜻하며, 프랑스어 텍스트의 문체와 리듬, 의미를 최대한 충실하게 옮기겠다는 의지를 담고 있습니다. 노벨문학상 수상 작가인 아니 에르노, 파트릭 모디아노와 밀리언셀러 작가 델핀 드 비강 등 프랑스 대표 작가들의 작품은 물론, 돌봄여성 살해상실 등 동시대의 사회적 문제를 정면으로 다룬 소설을 주로 소개합니다. 또한 예술철학과학 등 다양한 분야의 교양서를 통해 독자에게 새로운 시각과 사유의 계기를 제안합니다. 레모는 프랑스 문학이 난해하다는 편견을 넘어서기 위해, 정확한 번역과 충실한 해설을 바탕으로 한 권 한 권을 만들고 있습니다.', null, 'https://www.instagram.com/ed_lesmots/', 261),
  (262, 'B203', null, '스위밍꿀', 'SWIMMINGKUL', null, null, false, array['문학']::text[], '편집에 진심인 한국문학 전문 1인 출판사. 김화진 연작소설 『공룡의 이동 경로』, 박솔뫼 연작소설 『믿음의 개는 시간을 저버리지 않으며』, 이희주 연작소설 『사랑의 세계』, 정기현 첫 소설집 『슬픈 마음 있는 사람』, 한정현 첫 장편소설 『줄리아나 도쿄』 등 자신만의 세계가 뚜렷한 작가들의 소설을 출간했습니다. 스위밍꿀의 로고는 오리입니다. 오리는 물에서 헤엄칠 수도, 뭍에서 걸어다닐 수도 있는 동물입니다. 한 작가의 정체성이 짙게 담겨 있는 이야기라면, 스위밍꿀은 그것이 ‘물’에 속하든, ‘뭍’에 속하든, 기꺼이 출간합니다. 오리가 확장해가는 이야기의 세계를 기대하며, 오늘도 책을 만들고 있습니다', null, 'https://www.instagram.com/swimmingkul/', 262),
  (263, 'B204', null, '주식회사 도서출판점자', 'Braille Publishing Company', null, null, false, array['문학','아동','학습참고서']::text[], '모두에게 공평한 세상, 도서출판점자가 함께하겠습니다. 한국의 대표 배리어프리-프린팅하우스로서 점자촉각확대 자료 제작 및 보급을 통한 맞춤형 교육 서비스를 제공할 뿐 아니라 장애인이 실감하는 자신의 장애를 최소화할 수 있는 보조공학기기 대여 서비스까지도 제공하고자 노력하고 있습니다. 도서출판점자가 오늘, 이곳에서, 함께, 공동의 문제를 해결하며 책으로 사람과 사람을 연결하고, 우리와 세상을 매개하는 역할을 감당하길 소망합니다. 단순히 출판사를 넘어 장애인식개선과 교육격차를 해소하는 문제해결 단체가 되었으면 합니다. 누구나 타인과는 다른 특별한 차이점이 존재합니다. 특별함이 차별이 되지 않도록, 소외된 자들을 세상과 이어줄 점자가 참 기대됩니다. 함께 가는 길, 여러분의 많은 관심과 사랑을 부탁 드립니다.', 'https://www.kbraille.com/', 'https://www.instagram.com/bf_books/', 263),
  (264, 'B205', null, '후즈갓마이테일', 'Whos Got My Tail', null, null, false, array['예술','문학','아동']::text[], '"내 꼬리는 누가 가져갔을까?" 후즈갓마이테일은 이 질문 하나로 누구나 상상을 시작하고, 자신만의 이야기를 꿈꾸게 만드는 즐거움에서 출발했습니다. 우리는 이 유쾌한 질문을 동력으로, 기존의 틀에 갇히지 않은 독특한 감각과 경계 없는 기획으로 우리만의 결이 담긴 책을 만듭니다. 국내외 창의적인 작가들의 개성이 뚜렷하게 드러나는 작품을 지향하며, 장르와 형식을 넘나드는 과감한 시도를 통해 독자들에게 처음 만나는 즐거움을 선사합니다. 어린이를 웃게 만드는 재기발랄한 이야기부터 어른의 내면에 깊은 영감을 주는 일러스트북까지, 감각적인 디자인과 시대를 읽는 감성이 담긴 후즈갓마이테일의 책들이 독자들의 숨겨진 상상력을 깨우는 새로운 매개체가 되기를 바랍니다.', null, 'https://instagram.com/whosgotmytail/', 264),
  (265, 'B206', null, '흰토끼프레스(바캉스프로젝트)', 'Hintoki Press(Vacances)', null, null, false, array['예술','문학','아동']::text[], '바캉스는 그림책 작가 18명이 모여 한국의 옛이야기를 바탕으로 도전적이고 실험적인 독립출판물을 만드는 프로젝트 그룹입니다. 작가들은 창작 과정을 공유하고 서로 영감을 주고받으며, 개별 혹은 공동 작업을 통해 자유로운 표현을 모색하며 그림책의 외연을 확장해 왔습니다. 전시와 다양한 도서전 참가로 그림책을 사랑하는 독자들을 만나고 함께 성장합니다.', null, 'https://www.instagram.com/vacancesproject/', 265),
  (266, 'B207', null, 'SIBF × 글월 〈페이지 사이의 우체국〉', 'SIBF × geulwoll 〈The Post Office Between the Pages〉', null, null, true, '{}'::text[], null, null, null, 266),
  (267, 'B301', null, '도서출판 노란돼지', 'Yellowpig publisher', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '도서출판 노란돼지는 어린이와 함께 꿈꾸고 성장하는 좋은 친구 같은 책을 펴냅니다. 우리 출판사에는 세 개의 브랜드가 있습니다. 노란돼지는 어린이와 함께 꿈꾸고 성장하는 좋은 친구 같은 책을 만들고 싶다는 마음으로 재미와 의미를 모두 담은 그림책을 펴내고 있습니다. 달그림은 아이와 어른, 모두 공감할 수 있는 따뜻한 감성 그림책을 펴내고 있습니다. 초록서재는 여린 잎이 자라 짙은 나무가 되듯, 마음과 생각이 깊어지는 청소년 책을 펴내고 있습니다. 도서출판 노란돼지는 가만히 머물다가 따뜻한 말 한마디 건네는 다정한 친구처럼, 눈물이 날 만큼 하하 호호 같이 웃게 되는 재밌는 친구처럼, 독자들 곁에서 용기와 위로를 건네는 친구 같은 책을 만들겠습니다.', 'http://yellowpig.co.kr', 'https://www.instagram.com/yellowpig_pub/', 267),
  (268, 'B302', null, '늘보의 섬', 'SLOTH ISLAND', null, null, false, array['아동']::text[], '느릿느릿 살아가는 늘보들과 늘 놀고만 싶은 펭귄들을 위한 작은 섬을 만들어갑니다. 동요가 수록된 영유아 보드북, 모든 세대가 함께 보는 그림책, 청소년을 위한 그래픽노블 등을 출간했습니다. 그림책 캐릭터와 이야기를 기반으로 다양한 콘텐츠를 만들며 책의 영역을 확장해 나가고 있습니다.', 'http://www.slothisland.net', 'https://www.instagram.com/sloth.island/', 268),
  (269, 'B303', null, '(주)창비교육', 'CHANGBIEDU', null, null, false, array['문학','역사','아동']::text[], '창비교육은 창비의 교과서사업본부로 시작하여 2014년에 (주)창비교육 으로 법인을 독립하였습니다. 교과서와 참고서 등을 꾸준히 펴내며 성장해온 창비교육은 청소년시, 성장소설, 동화, 교양서 등으로 영역을 확장하여 청소년 분야에서 탄탄히 자리매김하고 있습니다. 청소년 분야는 교육출판사에서 출간하는 믿을 수 있는 읽을거리와 성장소설 시리즈와 창비청소년시선을 주측으로 자리를 공고히 해나가고 있습니다. 또한 성인 분야는 2025년 ''책깃'' 브랜드를 신설하여, 소설, 교양, 자기계발, 에세이 등 성인은 물론 청소년까지 재미있게 읽을 수 있는 다양한 분야의 책을 출간하고, 독서라는 새롭고 지적인 모험을 선사하여 독서의 즐거움과 독자의 성장을 함께 꾀하고자 합니다.', 'https://class.changbiedu.com/', 'https://www.instagram.com/changbiedu_book/', 269),
  (270, 'B304', null, '서해문집', 'Booksea Publishing Co.', null, null, false, array['사회과학','문학','역사']::text[], '서해문집은 책의 바다(書海)를 향해 40여 년 항해를 이어왔습니다. 고전, 역사, 인문, 사회과학을 바탕으로 문학, 예술, 과학까지 장르의 경계를 유연하게 넘나들며 다양한 독자들과 소통해왔습니다. 대표작으로는 ''징비록'' ''Jazz It Up!'' ''궤도(Orbital)'' ''앨버트로스의 똥으로 만든 나라'' 등이 있으며, ''서해문집 청소년 문학'' ''아시아의 미'' ''세상을 묻는 십대'' 시리즈도 꾸준히 선보이고 있습니다. 최근에는 일러스트가 결합된 인문교양서와 문학을 중심으로, 성인뿐만 아니라 청소년 독자에게 다양한 경험과 읽는 즐거움을 전하고 있습니다. 책에 한정되지 않은 다양한 물성의 콘텐츠를 통해 세대와 문화를 넘어 공감할 수 있는 이야기를 계속해서 이어가고자 합니다.', 'http://booksea.co.kr', 'https://www.instagram.com/booksea_pub/', 270),
  (271, 'B305', null, '한림사', 'HANLIMSA', null, null, false, array['예술']::text[], '저희는 해외 아트 서적 번역 출판 및 한국 일러스트 작가님 들의 책을 출판하는 것을 주업으로 하는 출판사입니다.', 'http://www.bookmarc.co.kr', null, 271),
  (272, 'B306', null, '나비클럽', 'NABICLUB', null, null, false, array['문학','기타(인문)']::text[], '나비클럽은 세상을 지적으로 탐구하고 새로운 시각을 발견하고자 하는 사람들에게 미스터리적 사고를 제안합니다. 미스터리는 단순한 장르가 아니라, 세상을 탐구하는 방식입니다. 미스터리는 예상하지 못한 뜻밖의 발견이며, 정해진 틀과 규칙 너머로 세상을 탐구하려는 호기심이자, 내 안의 편견을 인식하고 사유를 확장하는 질문입니다. 나비클럽은 단지 미스터리 장르의 책을 출간하는 것을 넘어 미스터리적 사고를 체험하는 경험을 전달합니다. 이를 통해 독자가 자기 생각의 틀을 넘어서고 새로운 시각을 발견하는 즐거움을 느끼며, 끊임없는 질문을 통해 세상을 더 넓고 깊게 탐구할 수 있도록 돕습니다.', 'http://www.nabiclub.net', 'https://www.instagram.com/nabiclub/', 272),
  (273, 'B307', null, '국립생태원', 'NIE PRESS', null, null, false, array['아동','학습참고서','기타(자연과학)']::text[], '국립생태원은 생태와 관련된 모든 것을 한곳에서 만날 수 있는 국가 생태 전문기관입니다. 한반도 생태계를 비롯해 열대, 사막, 지중해, 온대, 극지에 이르는 세계 5대 기후의 자연과 그곳에 서식하는 다양한 동식물을 관찰하고 체험할 수 있는 생태 연구, 전시, 교육 기관으로, 국내외 생태 연구를 선도하며 국민에게 생태계에 대한 폭넓은 배움의 기회를 제공하고 있습니다. 국립생태원 출판부는 이러한 연구, 전시, 교육 현장에서 축적된 생태 정보와 이야기를 바탕으로, 유아부터 성인, 전문가에 이르기까지 다양한 독자를 위한 생태문학, 정보도서, 연구총서, 전자출판 등 폭넓은 출판물을 개발하여 보급하고 있습니다. 연구와 전시, 그리고 교육의 현장을 책으로 담아냅니다.', 'http://www.nie.re.kr', null, 273),
  (274, 'B308', null, '퍼머넌트북스', 'Permanent Books', null, null, false, array['예술','문학','아동']::text[], '도서출판 북뱅크는 1999년 설립 이후, 유아 및 아동 서적 출판에 주력하며, 아이와 부모는 물론, 노년층까지 아우를 수 있는 그림책 전문 출판사를 지향하고 있습니다. 북뱅크는 그림책을 통해 사회적인 메시지에도 관심을 기울여, 어린이의 집단 따돌림 문제, 성폭력 문제는 물론, 인권과 평화를 다룬 책들, 그리고 어린이의 난치병 등에 대한 이야기도 다각적으로 소개하고 있습니다. 2026년 창립 27주년을 맞이한 북뱅크는, 그림책이라는 전문 분야를 확장하여 국내에서 아이들만의 책이라는 인식을 넘어서, 0세부터 100세까지 모두가 읽을 수 있는 장르로 자리잡기 위해 퍼머넌트북스 임프린트를 운영하고 있습니다.', 'https://bookbank-books.com/index.html', 'https://www.instagram.com/bookbank_books/', 274),
  (275, 'B309', null, '주식회사 한겨레엔', 'Hankyoreh En Co., Ltd.', null, null, false, array['사회과학','예술','문학']::text[], '안녕하세요, 한겨레출판입니다. 한겨레출판은 1994년 창립 이후 문학, 인문교양, 정치사회 분야에서 1500여 종의 책을 펴내며 한국 출판의 한 축을 담당해왔습니다. 30주년을 맞은 한겨레문학상은 심윤경, 박민규, 장강명, 최진영, 강화길, 박서련, 김홍 등 한국문학을 대표하는 작가들을 발굴해내며 한국문학의 산실로 자리매김했습니다. 김초엽, 조예은, 성해나, 강민영의 젊은 소설로 동시대를 감각하고, 박노자, 희정, 신형철의 사유로 삶의 본질을 파고들며, 김금희, 은유, 김진영, 전홍진의 시선으로 존재의 의미를 되새기면서, 이 시대의 가장 치열한 질문들과 함께 독자와 호흡하고 있습니다.', 'http://www.hanibook.co.kr', 'https://www.instagram.com/hanibook/', 275),
  (276, 'B400', 'B400', '책마을', 'Book Village', null, null, true, '{}'::text[], null, null, null, 276),
  (277, 'B400', 'B401', '누땡스', 'nu thanks', null, null, true, array['총류','예술','기타(잡지)']::text[], '일상 속에서 ''새로움''과 ''감사함''을 발견하고 느끼는 것을 추구하는 라이프 스타일 브랜드 *nu thanks는 2014년에 서울에서 시작하였습니다. "이 세상에 똑같은 사람은 한 명도 없다."라는 생각을 전제로 하여 다양한 사람들의 시선과 이야기를 공유할 수 있는 공간을 만드는 것을 목표로 하며, 공간의 형태에는 제한을 두지 않습니다. 2018년부터 출판사를 시작하면서 "하나의 공간을 만든다."라는 생각을 가지고 책을 만들고 있습니다. 사진집부터 산문집까지 다양한 장르의 도서들을 출판합니다. 지금은 브랜드의 이름과 동일한 이름의 매거진 [nu thanks]를 출간하는 일에 집중하고 있습니다.', 'http://www.nuthanks.com', 'https://instagram.com/nuthanks/', 277),
  (278, 'B400', 'B402', '텍스트 프레스', 'textpress.kr', null, null, true, array['철학','예술','문학','기타(디자인','에세이)']::text[], '부산의 생활예술 출판사 텍스트 프레스는 편집자이자 독립연구자, 타이포그래퍼인 정동규가 운영하는 출판사입니다. 우정을 기반으로 삶의 다양한 양태를 미학적·사회학적 관점에서 탐구하며, 글과 이미지, 디자인을 통해 새로운 삶의 방식을 담는 책을 만들어갑니다. 더불어 텍스트 프레스는 삶과 책 사이의 거리를 좁히는 출판 활동을 지향합니다. 일상 속에서 출판물의 형식을 실험하고, 한 권의 책이 만들어내는 여백과 움직임을 세심하게 살피며, 각자가 자신의 속도로 머물고 건너갈 수 있는 독서의 자리들을 만들어갑니다.', 'http://textpress.kr', 'https://www.instagram.com/textpress.kr/\/', 278),
  (279, 'B400', 'B403', '프레스탁!', 'press tac!', null, null, true, array['철학','사회과학']::text[], '탁!은 ‘고양이(cat)’라는 단어를 뒤집은 말입니다. 출판사 이름이 고양이의 시선으로 익숙한 세계를 뛰어넘는다는 의미를 담고 있듯, 우리는 동물권을 출발점으로 인간–비인간 관계, 젠더, 도시 생태학 등 서로 분리돼 온 영역을 책을 통해 연결합니다. 특히 도시에서 마주치는 동물들에 주목하며, 그중에서도 길고양이를 ‘경계 동물’로 바라봅니다. 인간 사회의 틈에서 살아가는 이 존재를 통해 공존의 가능성과 정치적 상상력을 확장하는 작업을 꾸준히 이어가고자 합니다.', 'https://blog.naver.com/presstac/223526305363', null, 279),
  (280, 'B400', 'B404', '225호', 'Room Number 225', null, null, true, array['예술']::text[], '225호에서 이이오가 그림을 그리며 책을 만들고 있습니다. 홀로 만든 독립출판물을 225호라는 이름의 출판사를 통해 세상에 내놓습니다. 225호의 책들이 공통적으로 가진 하나의 주제는, ‘이이오의 그림’입니다. 2019년 발간된 첫 책을 시작으로 『yolkasm』, 『뉴스와 데스크』, 『금요일의 얼굴들』 등 그림책, 컬러링북, 또는 만화책을 제작하고 있으며, 2026년 현재 총 6종의 도서를 출간하였습니다. 그림의 대상은 주로 사람, 고양이, 음식 등으로 작가가 오래도록 탐미하여 그 감상을 그림으로써 다른 사람들과 공유하고픈 것들입니다.', 'https://roomnumber225.com/room/bookshelf.html', 'https://www.instagram.com/blank225blue/', 280),
  (281, 'B400', 'B405', '라마북스', 'LLAMA BOOKS', null, null, true, array['예술','기타(만화)']::text[], '라마북스는 허안나 작가의 만화를 출간하는 1인 출판사입니다. 단순하지만 마음에 오래 남는 만화를 출판합니다.', null, 'https://www.instagram.com/llama__books/', 281),
  (282, 'B400', 'B406', '비바 헤리티지 시리즈', 'Viva Heritage Series', null, null, true, array['예술']::text[], '비바 헤리티지 시리즈 영화를 읽고, 감각하고, 소장하는 새로운 방식을 제안합니다. 비바 헤리티지 시리즈(이하 VHS)는 2025년, 20년 경력의 영화잡지 편집장, 20년 경력의 아트디렉터, 동시대 감각과 소통하는 에디터 3인이 결성한 크리에이티브 콜렉티브(창작 공동체)입니다. 우리는 영화를 ‘만지고 소장했던’ 비디오 시대 영화의 문화적 가치를 계승하고, 이를 물성과 감성이 작동하는 도서, 진(ZINE), 굿즈 등의 ‘경험’으로 확장시켜 오늘의 독자에게 건네고자 합니다. 2026년 서울국제도서전에서 VHS는 비디오 시대 영화를 현대적 키워드로 연결한 아트북 과 ‘보고 읽는’ 사람을 위한 굿즈를 선보입니다. 특히 내용의 전문성과 디자인의 독창성으로 2025년 11월 열린 17회 언리미티드 에디션에서 뜨거운 호응을 얻은 바 있습니다. 스트리밍의 시대, VHS는 다시금 영화를 ‘손에 쥐고, 서재에 꽂는’ 감각을 되돌려줄 것입니다.', 'http://www.viva-heritage-series.com', 'https://www.instagram.com/vhs.seoul/', 282),
  (283, 'B400', 'B407', '라우더북스', 'Louder Books', null, null, true, array['사회과학','예술','문학']::text[], '라우더북스는 『나의 미친 페미니스트 여자친구』 등을 쓴 소설가 민지형의 1인 출판사입니다. 세상에 필요한 시끄러운 소리들을 담은 책을 만듭니다. 질문하고, 흔들고, 때로는 불편함을 주는 책의 힘을 믿습니다. 지금 이곳의 감각을 놓치지 않는 이야기를 꾸준히 전합니다. 복잡하고 어려운 문제를 외면하지 않고, 재미있고 풍자적인 방식으로 다루고자 합니다. 소설·만화·에세이·사회과학서 등 다양한 형식을 통해 동시대의 문제를 새롭게 바라보는 시선을 제안합니다.', null, 'https://www.instagram.com/louderbooks/', 283),
  (284, 'B400', 'B408', '', 'Fidèle éditions', '프랑스', 'France', true, '{}'::text[], null, null, null, 284),
  (285, 'B400', 'B409', '', 'Owl & Dog Playbooks', '영국', 'UK', true, '{}'::text[], null, null, null, 285),
  (286, 'B400', 'B410', '프레스룸', 'PRESS ROOM', null, null, true, array['예술','기타(디자인)']::text[], '프레스룸은 서울을 기반으로 활동하는 그래픽 디자인 스튜디오이자 출판사입니다. 시각 예술 분야의 작가 및 작품 세계를 북 디자인과 유기적으로 연결하는 시도를 지속하며, 문화 예술 전반의 아이덴티티, 인쇄 매체, 디지털 및 물리적 공간 디자인을 아우릅니다. 2018년부터는 동시대 그래픽 디자인 전시 및 프로그램인 ORGD(Open Recent Graphic Design)를 기획·운영하고 있으며, 관련 기록을 연속발행물로 출판하며 디자인 담론을 확장하고 있습니다.', 'https://www.press-room.kr/publication/', null, 286),
  (287, 'B400', 'B411', '히스테리안', 'Hysterian', null, null, true, array['사회과학','예술','문학']::text[], '히스테리안은 2018년부터 동시대 예술과 인문 담론을 연결하며 시각 문화를 기획하고 출판사를 운영하고 있습니다. 문학, 철학, 인문, 예술을 가로지르는 단행본과 앤솔로지를 기획·출간하며, 리서치와 비평에 기반한 출판을 통해 사유의 축적과 확장을 이어오고 있습니다. ‘히스테리(Hysteria)’는 그리스어 어원에서 자궁(hystera)을 뜻하며, 이후 여성의 섹슈얼리티를 둘러싼 담론 속에서 병리적으로 규정되어 온 개념입니다. 히스테리안은 이 단어에 축적된 젠더화된 역사와 문화 권력의 흔적에 주목하고, 이를 동시대 사회의 정치적·문화적 정동을 탐구하는 출판적 질문으로 전환합니다. 이러한 관점을 바탕으로 히스테리안은 오늘의 삶과 예술을 비판적으로 사유하는 동시대적 출판을 지속적으로 선보이고 있습니다.', null, 'https://www.instagram.com/hysterian.public/', 287),
  (288, 'B400', 'B412', '행복한 재수가 있는', 'Happy Jaesu Press', null, null, true, array['종교','예술','아동','기타(만화에세이','그래픽노블)']::text[], '1인 출판사를 운영하며 애니메이션도 제작하고 있습니다. 종이책이 기획부터 제작, 인쇄까지 완성되는 전 과정을 좋아해, 대부분의 제작 과정에 직접 참여합니다. 어떤 이야기는 책과 애니메이션으로 동시에 제작하기도 합니다. 상상한 것을 자유롭게 표현할 수 있는 책의 매력과, 이미지를 살아 움직이게 할 수 있는 애니메이션의 매력을 모두 좋아합니다. 책은 이야기를 더 깊이 전할 수 있도록 도와주는 매체라고 생각합니다. 출판사의 이름은 ‘행복한 재수가 있는’입니다. ‘재수’는 우리나라에서 행운이라는 뜻으로 쓰이기도 하지만, 제 남편의 이름이기도 합니다. 남편 덕분에 행복하기 때문에, 남편도 행복하길 바라는 마음으로 이 이름을 짓게 되었습니다.', null, 'https://www.instagram.com/whitegrub/', 288),
  (289, 'B400', 'B413', '두낫프레스?프레스!', 'donotpress?press!', null, null, true, array['예술']::text[], 'do not press? press!는 모두가 출판을 말리는 이 시기에 굳이 출판하겠다는 고집과, 스스로를 압박해서라도 일을 진행하겠다는 다짐과, 누르지 말라고 하면 더 누르고 싶어지는 비뚤어진 호기심과, 누르지 말라는 그것을 기어이 누르고 말겠다는 만용을 한 데 담은 이름입니다. 이를 통해 (소위 말하는) 디자이너의 ‘개인 작업’과 같은 활동을 실행, 기록하게 됩니다. 모든 작업은 do not press? press!의 자장 아래서 시도하고 수행되겠지만, 이름처럼 출판의 형태만 고집하지는 않습니다. 그것은 영상이 될 수도, 퍼포먼스가 될 수도, 전시가 될 수도, 그리고 당연하게 책이 될 수도 있습니다. 그리고 어쩌면 그 어디에도 속하지 않는 어떤 것이 될지도요.', null, 'https://www.instagram.com/donotpress_press/', 289),
  (290, 'B400', 'B414', '자인운트', 'Seinund', null, null, true, array['예술']::text[], '자인운트는 사진가 이준식이 운영하는 1인 출판사입니다. 사진가 이준식은 사진을 매체로 한 작업을 책으로 출판하고 있습니다. 일상의 조각들을 수집하고 이를 동시대적인 맥락으로 재조립하여, 인간과 인간 주변을 둘러싼 존재들 간의 관계를 다른 방식으로 확인하고자 하는 책을 만들고자 합니다. 동시대에 흐르는 담론이 담긴 작업을 두고 사진가와 디자이너가 함께 의논하고, 책이라는 형태의 전시장으로 다시 만들고자 합니다. 그렇게 존재와 함께하는 그 무언가에, 책으로 연결될 수 있길 바랍니다. 『Scent mark』(2023), 사진 플립북 『Ways of Disappearing – 다른 방식으로 사라지기』(2024), 『Kisnuj Eel』(2024), 『오래된 실험들; 접은 형태』(2025)을 출간했습니다.', 'https://seinund.com', 'https://instagram.com/seinund/', 290),
  (291, 'B400', 'B415', '유연성클럽', 'THE FLEXIBILITY CLUB', null, null, true, array['예술']::text[], '유연성클럽 THE FLEXIBILITY CLUB은 예술 서적을 기획, 디자인하고 출판하는 소규모 프레스입니다. 만화, 일러스트, 그림책, 현대미술 등 다양한 시각 예술 분야의 작가들과 협업하는 동시에 다양한 자리의 창작자들과 함께하는 유연한 동아리를 지향합니다.', 'https://theflexibilityclub.com/', 'https://instagram.com/theflexibilityclub/', 291),
  (292, 'B400', 'B416', '메이커메이커', 'MAKERMAKER', null, null, true, array['예술']::text[], '메이커메이커는 아트북을 주로 만드는 출판사입니다. 현대의 예술, 디자인, 도시를 주제로 모노그래프를 발행하고 있으며 2023년 출간한 《클로징 세레모니: 힐튼 서울》은 2024 에 선정되었습니다. 주로 도시와 예술에 대한 소재를 중심으로 사람들이 얻는 영감과 관심을 가지는 대상을 탐구하며, 출판 주제와 함께 책의 작품성과 디자인을 고려합니다. 아티스트 모노그래프와 새로운 방법으로 도시 유산을 기록하는 《클로징 세레모니》 시리즈, 도시를 미술관처럼 산책하는 가이드 《아트 바이 아트》 시리즈를 통해 현 시대의 예술과 도시의 관계를 반영합니다. 메이커메이커는 서울과 런던에 위치한 디자인 스튜디오 그래픽캐뷰러리에서 운영합니다.', 'https://makermaker.ink/', 'https://www.instagram.com/makermaker.ink/', 292);
